class Solution:
    def findRestaurant(self, list1: list[str], list2: list[str]) -> list[str]:
        best = 10**18
        ans = []
        for i in range(len(list1)):
            for j in range(len(list2)):
                if list1[i] == list2[j]:
                    s = i + j
                    if s < best:
                        best = s
                        ans = [list1[i]]
                    elif s == best:
                        ans.append(list1[i])
        return sorted(ans)

