class Solution:
    def findRestaurant(self, list1, list2):
        a = sorted((name, i) for i, name in enumerate(list1))
        b = sorted((name, i) for i, name in enumerate(list2))
        i = j = 0
        best = 10**18
        ans = []
        while i < len(a) and j < len(b):
            if a[i][0] == b[j][0]:
                s = a[i][1] + b[j][1]
                if s < best:
                    best = s
                    ans = [a[i][0]]
                elif s == best:
                    ans.append(a[i][0])
                i += 1
                j += 1
            elif a[i][0] < b[j][0]:
                i += 1
            else:
                j += 1
        return sorted(ans)

