class Solution:
    def findRestaurant(self, list1, list2):
        pos = {name: i for i, name in enumerate(list1)}
        best = 10**18
        ans = []
        for j, name in enumerate(list2):
            if name in pos:
                s = pos[name] + j
                if s < best:
                    best = s
                    ans = [name]
                elif s == best:
                    ans.append(name)
        return sorted(ans)

